-- PT112-S3-Q1. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT112-S3-Q1$batch03$ AND q.stimulus=$batch03$Scientists agree that ingesting lead harms young children. More lead paint remains in older apartment buildings than newer ones because the use of lead paint was common until only two decades ago. Yet these same scientists also agree that laws requiring the removal of lead paint from older apartment buildings will actually increase the amount of lead that children living in older apartment buildings ingest.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent discrepancy in the scientists' beliefs?$batch03$ AND q.correct_choice=$batch03$D$batch03$) THEN RAISE EXCEPTION 'Question changed: PT112-S3-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT112-S3-Q1$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S3-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT112-S3-Q1$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Lead harms children, and old apartment buildings have more lead paint.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Scientists think laws requiring removal of that paint will *increase* how much lead those children ingest?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The removal itself must create a new route for lead. Paint sealed on a wall is hard to swallow. Scraping or sanding it off makes dust and chips that spread through the apartment.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a way the removal process puts more lead within children's reach.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT112-S3-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Lead-free paint being harmful in other ways does not explain more *lead* being ingested.$batch03$), ($batch03$B$batch03$, $batch03$Better uses for the money say nothing about lead levels after removal.$batch03$), ($batch03$C$batch03$, $batch03$Other sources supplying most of the lead might make removal pointless, but not harmful. It does not explain an *increase*.$batch03$), ($batch03$D$batch03$, $batch03$Removing the paint spreads lead dust, which children swallow more easily than paint on a wall. The law causes the very exposure it aims to prevent.$batch03$), ($batch03$E$batch03$, $batch03$Other hazards being worse does not explain how removing lead paint increases lead intake.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT112-S3-Q1$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
